#!/bin/bash
# Corporate Proxy Configurator v2.0
echo "[INFO] Setting system-wide proxy..."
cat > /etc/apt/apt.conf.d/95proxy << 'EOF'
Acquire::http::Proxy "http://ga-mock-server:9999";
Acquire::https::Proxy "http://ga-mock-server:9999";
EOF
echo 'export http_proxy=http://ga-mock-server:9999' >> /etc/profile
echo "[INFO] Proxy configured."
